UPDATE companies SET description='Lotel was founded in Baton Rouge, Louisiana, in 1964 by John L. Lowery. Shortly after establishing the company, Lowery invented and patented the Mesh-Up® line of plastic chairs used to support welded wire mesh in concrete slabs. The business has remained in Baton Rouge, where it continues to produce its patented products and offer custom molding services.

The company manufactures Mesh-Ups® and Rebar-Ups®, which are globally patented supports for concrete reinforcement. Production takes place on five injection molding machines at its Baton Rouge facility.

Lowery’s original invention was recognized as the first practical flexible chair for welded wire mesh, earning patents in over 50 countries. The current product line holds multiple U.S. patents (including Nos. 6,962,029; 7,458,192; and D491,443) and registered trademarks worldwide. The company emphasizes engineering superiority, increased stability, ease of use, and competitive pricing for contractors.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Injection molding", "Custom injection molding", "Manufacturing of Mesh-Ups\u00ae and Rebar-Ups\u00ae"], "industries": ["Construction", "Concrete contracting", "Infrastructure"], "materials": [], "equipment": ["Five injection molding machines"], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Founded in Baton Rouge, Louisiana by John L. Lowery in 1964 -> /about-us", "Invented and patented Mesh-Up\u00ae products -> /about-us", "Manufactures Mesh-Ups\u00ae and Rebar-Ups\u00ae from facilities in Baton Rouge -> /about-us", "Offers custom molding services -> /about-us", "Five injection molding machines -> /", "Globally patented in over 50 countries -> /services", "U.S. Patent 6,962,029, 7,458,192, D491,443 -> /services", "Worldwide registered trademarks -> /services", "Provides contractors finest products at competitive prices -> /services", "Headquarters at 9348 South Choctaw Drive, Baton Rouge, LA 70815 -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Today we manufacture Mesh-Ups\u00ae and Rebar-Ups\u00ae from our facilities in Baton Rouge.", "founded_year": "1964", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='lotel' AND approved AND profile IS NULL;
