UPDATE companies SET description='Louisa Food Products, Inc. operates from St. Louis, Missouri. The company traces its roots back over 50 years when St. Louis restaurateur Ferdinando Baldetti began producing scratch-made ravioli and pasta for local restaurants. Today, the business remains family-owned, now spanning four generations of the Baldetti family.

The company specializes in frozen, filled pasta products including toasted ravioli, ravioli, and tortellini. Production follows a daily scratch-kitchen approach: doughs are mixed from carefully milled wheat, vegetables are hand-chopped and roasted, meats are braised and stocks reduced in-house, cheeses are freshly grated, and pasta is made with semolina flour and eggs. The facility houses a culinary center for ongoing recipe development.

Louisa Foods serves both foodservice and retail channels.

The Baldetti family''s founding belief that "freshness matters" continues to drive operations. The company states its mission is to be recognized as the provider of high-quality frozen filled pasta, built on honesty, integrity, and responsiveness to customer needs.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Fresh pasta manufacturing", "Scratch cooking", "Meat grinding and dicing", "Vegetable chopping and roasting", "Stock reduction", "Cheese grating", "Frozen filled pasta production", "Recipe development", "Foodservice supply", "Retail distribution"], "industries": ["Foodservice", "Retail", "Restaurant"], "materials": ["USDA-graded meats", "Seafood", "Produce", "Herbs", "Semolina flour", "Eggs", "Domestic cheeses", "Imported cheeses"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Daily scratch production from whole ingredients", "Four-generation family recipes", "USDA-graded meats and produce", "In-house culinary center for product development", "No shortcuts in preparation methods"], "facts_used": ["Headquarters: St. Louis, Missouri -> db", "Founder: Ferdinando Baldetti -> /about", "Family-owned, four generations -> /about", "Products: toasted ravioli, ravioli, tortellini -> /", "Scratch kitchen methods: hand-chop vegetables, braise meats, grate cheese, make pasta with semolina and eggs -> /about", "Serves foodservice and retail -> /about", "Mission: leading provider of high-quality frozen filled pasta -> /about", "Culinary center for development -> /", "Address: 1918 Switzer Avenue, St. Louis, MO 63136 -> /about", "LinkedIn URL -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Louisa Foods starts all our pasta recipes with whole, fresh ingredients prepped from scratch.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": ["https://www.linkedin.com/company/louisa-foods/"], "ownership_tags": ["Fami