UPDATE companies SET description='Lumen Food Labs LLC, operating under the Lumen Brands name, is headquartered in Chicago, Illinois. The company was founded in 2020.

The firm provides master distributor and compliance services for consumer packaged goods (CPG) brands seeking to enter the U.S. market. Its offerings include Foreign Supplier Verification Program (FSVP) and Qualified Importer (QI) management, FDA-certified third-party logistics (3PL) warehousing, and acting as importer of record, customs broker, clearing house, insurer, and FDA responsible party. Lumen purchases inventory upfront at wholesale prices and provides monthly accounting, sales reporting, and forecasting from its Chicago warehouse facility.

Brand partners engage the company to handle facility registration, product identification, and all shipment-level compliance obligations for goods entering the United States.

The company differentiates itself by committing to purchase products upfront with no contingency, matching brand partners'' investments dollar-for-dollar, and tying its own profitability directly to the successful sale of those products. This model is designed to align incentives and reduce risk for brands expanding into the U.S. market.', certifications=ARRAY['FDA REGISTERED']::text[], profile='{"capabilities": ["Master Distributor Services", "FSVP/QI Services", "Compliance Services (record, collect, assess, develop, execute)", "Foreign Supplier Verification Program Services", "FDA Certified 3PL Services for CPG Products", "Importer of Record (IOR) Services", "Customs Brokerage", "Clearing House Services", "Insurance Services", "FDA Responsible Party Services", "Monthly Accounting, Sales Reporting, and Forecasting", "Upfront Product Purchasing at Wholesale"], "industries": ["Consumer Packaged Goods (CPG)"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Upfront purchase of inventory at wholesale pricing", "Dollar-for-dollar investment matching with brand partners", "Profit-sharing model: revenue only from product sales", "Full FSVP/QI and FDA regulatory compliance management", "Single-point service as importer of record, customs broker, and FDA responsible party"], "facts_used": ["Founded in 2020 -> db", "Headquarters in Chicago, Illinois -> db and page /", "FDA REGISTERED certification -> db", "Master Distributor Services -> db capabilities", "FSVP/QI Services -> db capabilities", "FDA certified 3PL services for CPG products -> db capabilities", "Acts as importer of record, customs broker, FDA responsible party -> db products", "Upfront purchase at wholesale pricing -> db products", "Dollar-for-dollar investment matching -> db products", "Profit only when client profits -> db products", "Monthly accounting, sales reports, forecasting -> db capabilities", "LinkedIn URL -> db linkedin_url", "Website lumenbrands.co -> db website"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "Master Distributor Services; Includes FDA certified and mainstream complaint 3PL services - designed exclusively for CPG products!", "founded_year": "2020", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": ["FDA Registered", "FSVP/QI compliance", "Customs broker services"], "languages": [], "social_links": ["https://www.linkedin.com/company/lumen-brands/"], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='lumen-food-labs-llc' AND approved AND profile IS NULL;
UPDATE companies SET description='Founded in 1984 in North Wilkesboro, North Carolina, LuRay Textiles, Inc. operates as a manufacturer of knitted fabrics. The company has remained in the same community for decades, producing textiles from a facility on Luray Road.

The company produces a range of knitted fabrics using American-made yarn, working with fibers that include cotton, polyester, and high-performance aramids such as Kevlar®, Nomex®, and PBI®. In addition to fabric rolls, LuRay manufactures wiping cloths and rags sized for tasks ranging from automotive detailing to furniture finishing.

LuRay’s fabrics serve the apparel and safety-apparel sectors, providing material for protective clothing and everyday wear. Its wiping-cloth line reaches automotive aftermarket customers for cleaning and detailing, as well as woodworking and furniture shops for stain and varnish application.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Knitted fabric manufacturing", "Wiping cloth manufacturing"], "industries": ["Apparel", "Safety apparel", "Automotive cleaning", "Furniture finishing"], "materials": ["Cotton", "Polyester", "Kevlar\u00ae", "Nomex\u00ae", "PBI\u00ae"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["American-made yarn sourcing", "Range of high-performance fibers including Kevlar, Nomex, PBI", "Wiping cloth production for diverse applications", "Domestic manufacturing in the USA"], "facts_used": ["Founded 1984 -> db", "Headquarters North Wilkesboro, NC -> db", "Manufacturer of knitted fabrics -> page /", "Uses American-made yarn -> page /", "Offers fabrics from cotton, polyester, Kevlar, Nomex, PBI -> page /", "Produces wiping cloths for car cleaning and furniture varnish -> page /", "Serves apparel and safety apparel markets -> page /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "LuRay Textiles, Inc. is a manufacturer of knitted fabrics.", "founded_year": "1984", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='luray-textiles-inc-plant-not-the-store' AND approved AND profile IS NULL;
UPDATE companies SET description='M-Tron Components Inc. was founded in 1984 in Ronkonkoma, New York. The company operates as a veteran-owned small business and a franchised distributor of electronic components, emphasizing a secure supply chain for military and commercial customers.

The firm stocks a broad inventory of semiconductors, resistors, capacitors, interconnect devices, and computer products from authorized manufacturers. Value-added services include mil-spec packaging per MIL-STD-2073, barcoding and RFID tagging to MIL-STD-129, kitting, tape-and-reel, printed circuit board assembly, and a proprietary search-and-sell network for obsolete or allocated parts. Quality management is certified to ISO 9001:2015 and AS9120:2016, the latter addressing aerospace chain-of-custody and anti-counterfeit controls.

Primary customers are the U.S. Government, its subcontractors, and OEMs in the military and aerospace sectors. M-Tron is a certified NDAA (H.R. 1540) supplier and participates in Lockheed Martin’s Star Supplier Program. The company also serves commercial accounts requiring RoHS-compliant components and traceable documentation.

M-Tron differentiates itself through a counterfeit-free zone backed by AS9120 anti-counterfeit measures, veteran-owned status, and a commitment to turning procurement challenges into production-ready assemblies. Its franchised distributor relationships and authorized product lines ensure genuine, traceable components for high-reliability applications.', certifications=ARRAY['ISO 9001:2015','AS9120:2016','RoHS','NDAA (H.R. 1540) certified']::text[], profile='{"capabilities": ["Electronic component distribution", "Mil-spec packaging (MIL-STD-2073)", "Barcoding and RFID tagging (MIL-STD-129)", "Kitting", "Tape and reel", "Printed circuit board assembly", "Obsolete/hard-to-find parts sourcing (Search and Sell Network)", "RoHS compliance support", "Authorized product line distribution"], "industries": ["Military", "Aerospace", "Government", "Commercial"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Counterfeit-free zone with AS9120:2016 anti-counterfeit controls", "Veteran-owned small business with NDAA (H.R. 1540) certification", "Franchised distributor for authorized product lines", "Mil-spec packaging per MIL-STD-2073 and barcoding per MIL-STD-129 with RFID", "Search-and-sell network for obsolete and hard-to-find parts"], "facts_used": ["Founded 1984 -> db", "Headquarters Ronkonkoma, New York -> db", "Veteran-owned small business -> /", "Certified ISO 9001:2015 and AS9120:2016 -> /", "Franchised distributor for Marl International -> /", "Mil-spec packaging per MIL-STD-2073 -> /", "Barcoding to MIL-STD-129 with RFID -> /", "RoHS compliance commitment -> /", "Search and Sell Network for obsolete parts -> /", "Supplier to U.S. Government and subcontractors -> /", "NDAA certified (H.R. 1540) -> /", "Lockheed Martin Star Supplier Program -> /", "Services: PC Board Assembly, Kitting, Tape & Reel -> /", "Authorized product lines -> /"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "M-TRON Components - Electronic Component Distributor for Military and Commercial Applications", "founded_year": "1984", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Veteran-owned", "Small business"]}'::jsonb, updated_at=now() WHERE slug='m-tron-components-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='M.S. Fabrication operates from a large warehouse in Dorchester Center, Massachusetts, just south of downtown Boston.

The shop runs a range of forming, cutting, and welding equipment. Forming capacity includes a 12-foot Accurpress 250-ton press brake, a 10-foot Trumpf V-130 six-axis 140-ton press brake, 60-inch pyramid rolls with a 6-inch top roll, and a Buffalo angle, flat bar, and tube rolling machine. Cutting is handled by a 10-foot Accurshear hydraulic shear rated for 3/8-inch aluminum, 1/4-inch steel, and 3/16-inch stainless; a 60-by-120-inch Omax CNC water jet capable of cutting up to 6-inch thickness; and a Euromax BX 1000 with 38-inch throat and 100-ton capacity. Welding resources comprise a Miller Dynasty 350 AC/DC TIG, a Miller Matic 250 MIG with Aim spool gun, a 20-inch throat spot welder, and a 1200W fiber laser welder. The facility works with all common steel, stainless steel, and aluminum alloys.

M.S. Fabrication serves customers requiring custom sheet metal work, but specific industry sectors or named clients are not listed in its public materials.

