tering Health Network partnership mention -> /"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "Medical Service Company is a Post-Acute Healthcare Provider that specializes in Sleep Disorder and Chronic-Respiratory Disease Management.", "founded_year": "1950", "employee_count": "hundreds", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='medical-service-company-lewis-center' AND approved AND profile IS NULL;
